mapper.select:
select id, house_id, tag_uid, target_type, target_id, rabbit_id, record_id, request_id, remark, create_by, create_time, update_by, update_time
from nfc_tags
where house_id = #{houseId}
  and tag_uid = #{tagUid}
limit 1

select id, house_id, tag_uid, target_type, target_id, rabbit_id, record_id, request_id, remark, create_by, create_time, update_by, update_time
from nfc_tags
where house_id = #{houseId}
  and target_type = #{targetType}
  and target_id = #{targetId}
limit 1

select t.id, t.house_id, t.tag_uid, t.target_type, t.target_id, t.rabbit_id, t.record_id, t.remark, t.create_time, t.update_time, case when t.target_type = 'CAGE' then c.cage_number when t.target_type = 'FEED' then '投喂' when t.target_type = 'SALE' then '销售' when t.target_type = 'TREATMENT' then concat('兔#', t.rabbit_id) else null end as target_name from nfc_tags t left join cages c on c.id = t.target_id and t.target_type = 'CAGE' where t.house_id = #{houseId}
and t.tag_uid = #{tagUid}
and t.target_type = #{targetType}
and t.target_id = #{targetId}
order by t.update_time desc, t.id desc limit #{limit} offset #{offset}

mapper.delete:
delete from nfc_tags
where house_id = #{houseId}
  and tag_uid = #{tagUid}

delete from nfc_tags
where house_id = #{houseId}
  and target_type = #{targetType}
  and target_id = #{targetId}
